import { Chess } from 'chess.js';
import { CHESS_TRAINERS } from '../data/chessTrainers';
import { CHESS_LESSONS, CHESS_PUZZLES } from '../data/chessLearning';

function prepareExercise<T extends { fen: string; from: string; to: string; promotion?: string }>(exercise: T) {
  const chess = new Chess(exercise.fen);
  const side = chess.turn();
  const move = chess.moves({ verbose: true }).find(candidate => candidate.from === exercise.from && candidate.to === exercise.to && (!exercise.promotion || candidate.promotion === exercise.promotion));
  if (!move) throw new Error(`Invalid chess exercise ${exercise.from}-${exercise.to} in ${exercise.fen}`);
  const played = chess.move({ from: move.from, to: move.to, promotion: exercise.promotion });
  return { ...exercise, side, solvedFen: chess.fen(), answerSan: played.san, checkmate: chess.isCheckmate() };
}

