var accountId=tgUser&&tgUser.id?'tg'+tgUser.id:'guest';var creatorEloMigrationKey='cg-chess-elo-200-migration-v1';var isBotCreator=false,creatorProfileReady=Promise.resolve();var chessTrainers=JSON.parse(decodeURIComponent('__CHESS_TRAINERS_URI__'));var chessLessons=JSON.parse(decodeURIComponent('__CHESS_LESSONS_URI__'));var chessPuzzles=JSON.parse(decodeURIComponent('__CHESS_PUZZLES_URI__'));var selectedChessTrainerId='';dailyChessPuzzleId=chessPuzzles[Math.floor(Date.now()/86400000)%chessPuzzles.length].id;
var CHESS_COUNTRY_CODES='AD AE AF AG AI AL AM AO AQ AR AS AT AU AW AX AZ BA BB BD BE BF BG BH BI BJ BL BM BN BO BQ BR BS BT BV BW BY BZ CA CC CD CF CG CH CI CK CL CM CN CO CR CU CV CW CX CY CZ DE DJ DK DM DO DZ EC EE EG EH ER ES ET FI FJ FK FM FO FR GA GB GD GE GF GG GH GI GL GM GN GP GQ GR GS GT GU GW GY HK HM HN HR HT HU ID IE IL IM IN IO IQ IR IS IT JE JM JO JP KE KG KH KI KM KN KP KR KW KY KZ LA LB LC LI LK LR LS LT LU LV LY MA MC MD ME MF MG MH MK ML MM MN MO MP MQ MR MS MT MU MV MW MX MY MZ NA NC NE NF NG NI NL NO NP NR NU NZ OM PA PE PF PG PH PK PL PM PN PR PS PT PW PY QA RE RO RS RU RW SA SB SC SD SE SG SH SI SJ SK SL SM SN SO SR SS ST SV SX SY SZ TC TD TF TG TH TJ TK TL TM TN TO TR TT TV TW TZ UA UG UM US UY UZ VA VC VE VG VI VN VU WF WS XK YE YT ZA ZM ZW'.split(' ');
