function sudokuTicketDay(){var date=new Date();return date.getFullYear()+'-'+String(date.getMonth()+1).padStart(2,'0')+'-'+String(date.getDate()).padStart(2,'0')}
function sudokuBattleTickets(){var day=sudokuTicketDay(),record;try{record=JSON.parse(localStorage.getItem(sudokuTicketKey)||'null')}catch(e){record=null}if(!record||record.day!==day||!Number.isFinite(Number(record.balance))){record={day:day,balance:5};try{localStorage.setItem(sudokuTicketKey,JSON.stringify(record))}catch(e){}}record.balance=Math.max(0,Math.min(5,Math.floor(Number(record.balance)||0)));if(record.pendingAt&&Date.now()-Number(record.pendingAt)>120000){record.balance=Math.min(5,record.balance+1);delete record.pendingAt;try{localStorage.setItem(sudokuTicketKey,JSON.stringify(record))}catch(e){}}return record}
function reserveSudokuBattleTicket(){var record=sudokuBattleTickets();if(record.balance<1||record.pendingAt)return false;record.balance--;record.pendingAt=Date.now();try{localStorage.setItem(sudokuTicketKey,JSON.stringify(record));return record.pendingAt}catch(e){return false}}
function settleSudokuBattleTicket(ticket){if(!ticket||!ticket.ticketReserved||ticket.ticketSettled)return;var record=sudokuBattleTickets();if(Number(record.pendingAt)===Number(ticket.ticketReservationAt)){delete record.pendingAt;try{localStorage.setItem(sudokuTicketKey,JSON.stringify(record))}catch(e){}}ticket.ticketSettled=true}
function refundSudokuBattleTicket(ticket){if(!ticket||!ticket.ticketReserved||ticket.ticketSettled)return;var record=sudokuBattleTickets();if(Number(record.pendingAt)===Number(ticket.ticketReservationAt)){record.balance=Math.min(5,record.balance+1);delete record.pendingAt;try{localStorage.setItem(sudokuTicketKey,JSON.stringify(record))}catch(e){}}ticket.ticketSettled=true;ticket.ticketReserved=false}

function getGameStats(game){try{var stats=JSON.parse(localStorage.getItem(statsKey(game)))||{};stats.matches=Number(stats.matches)||0;stats.wins=Number(stats.wins)||0;stats.bestTime=Number(stats.bestTime)||0;stats.seen=Array.isArray(stats.seen)?stats.seen:[];stats.done=Array.isArray(stats.done)?stats.done:[];return stats}catch(e){return {matches:0,wins:0,bestTime:0,seen:[],done:[]}}}
