function recordSudokuOpen(stats,category,difficulty){prepareSudokuProfile(stats);category=category==='friend'?'friend':category==='battle'?'battle':'classic';difficulty=['easy','medium','hard'].includes(difficulty)?difficulty:'easy';[stats.categories[category][difficulty],stats.categories[category].all].forEach(function(record){record.matches++;record.lastUpdated=Date.now()})}
