function applyRoom(data){
  roomData=data;
  var r=data.room,state=data.state,now=Date.now();
  activeRoomGame=r.game;
  document.body.classList.toggle('chess-match-open',r.game==='chess'&&r.status==='playing');
  document.body.classList.toggle('sudoku-friend-waiting',r.game==='sudoku'&&state?.mode==='friend'&&r.status==='waiting');
  updateChessChatUnread(r,state);
  var showIntro=r.game==='chess'&&state?.mode==='friend'&&r.status==='playing'&&(r.players||[]).length===2&&Number(state.matchIntroUntil)>now&&chessIntroRoomId!==r.id;
  if(showIntro)chessIntroRoomId=r.id;
  var playerSignature=(r.players||[]).map(function(player){return player.seat+':'+player.name}).join('|');
  if(lastPlayerSignature&&playerSignature!==lastPlayerSignature&&r.players.length>lastPlayerCount){var joined=r.players.find(function(player){return !lastPlayerSignature.includes(player.seat+':'+player.name)});if(joined&&joined.seat!==r.playerSeat)toast(joined.name+' انضم للغرفة')}
  lastPlayerSignature=playerSignature;lastPlayerCount=(r.players||[]).length;
  if(r.game==='chess'&&r.status==='finished'&&r.players[r.playerSeat]?.elo){var finalElo=Number(r.players[r.playerSeat].elo)||200;localStorage.setItem('cg-chess-elo-'+accountId,String(finalElo));localStorage.setItem('cg-chess-best-elo-'+accountId,String(Math.max(finalElo,Number(localStorage.getItem('cg-chess-best-elo-'+accountId))||chessElo())))}
  if(r.status==='finished'){
    var won=false;
    if(r.game==='chess')won=state.winnerSeat===r.playerSeat;
    else if(r.game==='sudoku')won=!!state.winner;
    else if(r.game==='uno')won=state.winnerSeat===r.playerSeat;
    else if(r.game==='poker')won=(state.winners||[]).includes(r.playerSeat);
    else if(r.game==='gartic'){var scores=state.scores||[],top=Math.max(0,...scores.map(function(item){return Number(item.score)||0}));won=top>0&&Number(scores[r.playerSeat]?.score||0)===top}
    var chessOpponent=(r.players||[]).find(function(player){return player.seat!==r.playerSeat});
    recordGameFinish(r.game,r.id,won,r.game==='chess'?{opponent:chessOpponent?.name||'الخصم',opponentType:chessOpponent?.bot?'bot':'player',result:state.result,clockMinutes:state.clockMinutes,winnerSeat:state.winnerSeat,eloChange:r.players[r.playerSeat]?.eloChange||0}:r.game==='sudoku'?{elapsedSeconds:Math.max(1,Math.floor(((Number(state.finishedAt)||Date.now())-(Number(state.startedAt)||Date.now()))/1000)),category:state.mode==='friend'?'friend':'battle',difficulty:state.difficulty,mistakes:state.mistakes}:undefined)
  }
  $('roomTitle').textContent=r.gameName;
  $('roomSubtitle').textContent='غرفة '+r.id+' · '+(r.status==='waiting'?'بانتظار اللاعبين':r.status==='playing'?'اللعب شغّال':'انتهت الجولة');
  $('inviteButton').onclick=inviteFriend;
  $('inviteButton').hidden=!canInvite(r,state)||(r.game==='sudoku'&&state.mode==='friend'&&r.status==='waiting');
  var signatureState=Object.assign({},state,{roundLeft:0,roundExpired:state.roundLeft<=0});delete signatureState.clocks;delete signatureState.clockRunning;
  var signature=JSON.stringify({room:r,state:signatureState});
  if(signature!==lastSignature&&!paintBusy){
    lastSignature=signature;
    var guessDraft=$('guessInput')?.value||'',chatInput=$('chessChatInput'),chatDraft=chatInput?.value||'',chatFocused=chatInput===document.activeElement,chatStart=chatFocused?chatInput.selectionStart:0,chatEnd=chatFocused?chatInput.selectionEnd:0,chatLog=$('chessChatMessages'),chatAtBottom=chatLog?chatLog.scrollHeight-chatLog.scrollTop-chatLog.clientHeight<32:true,chatOldScroll=chatLog?chatLog.scrollTop:0;
    renderGame(r,state);
    var guessBox=$('guessInput');if(guessBox&&guessDraft)guessBox.value=guessDraft;
    chatInput=$('chessChatInput');if(chatInput&&chatDraft)chatInput.value=chatDraft;
    if(chatInput&&chatFocused){chatInput.focus({preventScroll:true});chatInput.setSelectionRange(chatStart,chatEnd)}
    chatLog=$('chessChatMessages');if(chatLog)chatLog.scrollTop=chatAtBottom?chatLog.scrollHeight:chatOldScroll;
  }else{var timer=$('roundTimer');if(timer)timer.textContent=digit(state.roundLeft)+'ث';if(r.game==='chess')updateChessClockDisplay(state)}
  if(showIntro)showChessMatchIntro(r,state);
  if(r.game==='uno'&&selectedUno&&!(state.hand||[]).some(function(card){return card.id===selectedUno}))selectedUno='';
  if(r.game==='chess')maybeMoveChessBot(data)
}

async function inviteFriend(){if(!roomData)return;try{var link=await roomUrl();var title=roomData.room.gameName;var text='تعال نلعب '+roomData.room.gameName+'!';if(tg&&tg.openTelegramLink)tg.openTelegramLink('https://t.me/share/url?url='+encodeURIComponent(link)+'&text='+encodeURIComponent(text));else if(navigator.share)await navigator.share({title,text,url:link});else if(navigator.clipboard){await navigator.clipboard.writeText(text+'\n'+link);toast('نسخت رابط الدعوة')}else prompt('انسخ الدعوة',text+'\n'+link)}catch(e){toast(e.message||'تعذر إنشاء رابط الدعوة')}}
