function chessMessageKey(message){return String(message.id||([message.at,message.seat,message.text].join(':')))}
function syncChessChatUnread(){var button=$('chessChatButton');if(!button)return;var dot=button.querySelector('.chess-chat-unread-dot');if(dot)dot.hidden=!(chessChatUnread&&chessChatExpanded!==true);button.classList.toggle('has-unread',chessChatUnread&&chessChatExpanded!==true);button.setAttribute('aria-label',chessChatExpanded?'إغلاق محادثة المباراة':'فتح محادثة المباراة')}
