function ensureStockfishReady(){
  if(stockfishReady)return stockfishReady;
  if(!window.Worker)return Promise.reject(new Error('متصفحك لا يدعم محرك الشطرنج'));
  stockfishReady=new Promise(function(resolve,reject){
    var settled=false,worker=null,timer=setTimeout(function(){
      if(settled)return;
      settled=true;stockfishReady=null;if(worker)worker.terminate();if(stockfishWorker===worker)stockfishWorker=null;
      reject(new Error('انتهت مهلة تحميل محرك الشطرنج'))
    },15000);
    try{
      worker=new Worker('/stockfish/stockfish-19-lite-single.js');stockfishWorker=worker;
      worker.onmessage=function(event){
        var line=String(event.data||'').trim();
        if(line==='uciok'){worker.postMessage('isready');return}
        if(line==='readyok'&&!settled){settled=true;clearTimeout(timer);resolve(worker);return}
        if(line.startsWith('bestmove ')&&stockfishPending){
          var pending=stockfishPending;stockfishPending=null;clearTimeout(pending.timer);
          var uci=line.split(/\s+/)[1];
          if(!/^[a-h][1-8][a-h][1-8][qrbn]?$/.test(uci))pending.reject(new Error('محرك الشطرنج لم يرجّع نقلة'));
          else pending.resolve({from:uci.slice(0,2),to:uci.slice(2,4),promotion:uci[4]||'q'})
        }
      };
      worker.onerror=function(){
        var error=new Error('تعذّر تشغيل محرك الشطرنج');clearTimeout(timer);
        if(stockfishPending){clearTimeout(stockfishPending.timer);stockfishPending.reject(error);stockfishPending=null}
        if(!settled){settled=true;reject(error)}
        stockfishReady=null;if(stockfishWorker===worker)stockfishWorker=null
      };
      worker.postMessage('uci')
    }catch(error){clearTimeout(timer);stockfishWorker=null;stockfishReady=null;reject(error)}
  });
  return stockfishReady
}
async function stockfishMove(fen,elo){
  var worker=await ensureStockfishReady();
  return new Promise(function(resolve,reject){
    if(stockfishPending){reject(new Error('محرك الشطرنج مشغول'));return}
    var rating=Math.max(200,Math.min(2800,Number(elo)||200));
    var timer=setTimeout(function(){if(stockfishPending){stockfishPending=null;reject(new Error('تأخر محرك الشطرنج'))}},10000);
    stockfishPending={resolve:resolve,reject:reject,timer:timer};
    try{
      worker.postMessage('ucinewgame');
      worker.postMessage('setoption name Skill Level value '+Math.max(0,Math.min(20,Math.round((rating-200)/130))));
      worker.postMessage('position fen '+fen);
      worker.postMessage('go movetime '+Math.round(350+((rating-200)/2600)*2650))
    }catch(error){clearTimeout(timer);stockfishPending=null;reject(error)}
  })
}
