function wireSudoku(r,s){$('roomContent').querySelectorAll('[data-sudoku-cell]').forEach(function(el){el.onclick=function(){var index=Number(el.dataset.sudokuCell);if(s.puzzle[index])return;selectedSudokuCell=index;renderGame(r,s)}});$('roomContent').querySelectorAll('[data-sudoku-number]').forEach(function(el){el.onclick=function(){if(selectedSudokuCell<0){toast('اختار خانة فارغة أولاً');return}var index=selectedSudokuCell,value=Number(el.dataset.sudokuNumber);if(sudokuPencilMode){var notes=sudokuNotes[index]||[];sudokuNotes[index]=notes.includes(value)?notes.filter(function(n){return n!==value}):notes.concat([value]).sort();renderGame(r,s);return}sudokuNotes[index]=[];act('place',{index:index,value:value});selectedSudokuCell=-1}});$('roomContent').querySelectorAll('[data-sudoku-tool]').forEach(function(button){button.onclick=function(){var tool=button.dataset.sudokuTool;if(tool==='pencil'){sudokuPencilMode=!sudokuPencilMode;renderGame(r,s)}else if(tool==='undo'){if(s.canUndo)act('undo')}else if(tool==='erase'){if(selectedSudokuCell<0){toast('اختار خانة أولاً');return}sudokuNotes[selectedSudokuCell]=[];act('clear',{index:selectedSudokuCell});selectedSudokuCell=-1}}})}
function parseFen(fen){var rows=fen.split(' ')[0].split('/');return rows.reverse().map(row=>{var cells=[];for(var ch of row){if(/[1-8]/.test(ch))for(var i=0;i<Number(ch);i++)cells.push(null);else cells.push({color:ch===ch.toUpperCase()?'w':'b',type:ch.toLowerCase()})}return cells})}
