function wireCanvas(s){var canvas=$('drawCanvas');if(!canvas)return;var ctx=canvas.getContext('2d');ctx.lineCap='round';ctx.lineJoin='round';(s.strokes||[]).forEach(st=>{ctx.strokeStyle=st.color;ctx.lineWidth=st.size;ctx.beginPath();st.points.forEach((p,i)=>{var x=p[0]*canvas.width,y=p[1]*canvas.height;if(i)ctx.lineTo(x,y);else ctx.moveTo(x,y)});ctx.stroke()});$('roomContent').querySelectorAll('.palette-color[data-color]').forEach(b=>{b.classList.toggle('active',b.dataset.color===drawColor);b.onclick=()=>{drawColor=b.dataset.color;$('roomContent').querySelectorAll('.palette-color').forEach(x=>x.classList.toggle('active',x===b))}});var size=$('drawSize');if(size){size.value=String(drawSize);size.onchange=()=>{drawSize=Math.max(2,Math.min(20,Number(size.value)||5))}}canvas.onpointerdown=e=>{if(!roomData.state.isDrawer)return;drawing=true;paintBusy=true;canvas.setPointerCapture(e.pointerId);var rect=canvas.getBoundingClientRect();window._points=[[Math.max(0,Math.min(1,(e.clientX-rect.left)/rect.width)),Math.max(0,Math.min(1,(e.clientY-rect.top)/rect.height))]]};canvas.onpointermove=e=>{if(!drawing)return;var rect=canvas.getBoundingClientRect(),p=[Math.max(0,Math.min(1,(e.clientX-rect.left)/rect.width)),Math.max(0,Math.min(1,(e.clientY-rect.top)/rect.height))];window._points.push(p);ctx.strokeStyle=drawColor;ctx.lineWidth=drawSize;ctx.beginPath();var prev=window._points[window._points.length-2];ctx.moveTo(prev[0]*canvas.width,prev[1]*canvas.height);ctx.lineTo(p[0]*canvas.width,p[1]*canvas.height);ctx.stroke()};var finish=async()=>{if(!drawing)return;drawing=false;var points=window._points||[];paintBusy=false;if(points.length>1)await act('stroke',{points,color:drawColor,size:drawSize});await pollRoom()};canvas.onpointerup=finish;canvas.onpointercancel=finish;var form=$('guessForm');if(form)form.onsubmit=e=>{e.preventDefault();sendGuess()}}
