  var visiblePlayers=players.map((p,i)=>'<div class="poker-player '+(s.turnSeat===i?'active':'')+'"><b>'+safe(p.name)+(p.folded?' · انسحب':'')+'</b><br>رقائق '+digit(p.chips)+(p.cards?.length?' · '+p.cards.map(c=>cardText(c)).join(' '):' · 🂠 🂠')+'</div>').join('');
