const INVITE_GAME_NAMES: Record<string, string> = { chess: 'شطرنج', sudoku: 'سودوكو', uno: 'أونو', gartic: 'ارسم وخمّن', poker: 'بوكر تكساس' };
export function interactiveGamesMiniAppHtml(game = ''): string {
  const gameName = INVITE_GAME_NAMES[game] || '';
  const title = gameName ? `Code Games | ${gameName}` : 'Code Games | الألعاب التفاعلية';
  const description = gameName ? `انضم إلى صديقك في ${gameName} داخل Code Games. العبوا مباشرة من المتصفح.` : 'ألعاب Code Games التفاعلية — العب مباشرة من المتصفح وشارك رابط غرفتك.';
  const lessons = CHESS_LESSONS.map(lesson => ({ ...lesson, exercise: prepareExercise(lesson.exercise) }));
  const puzzles = CHESS_PUZZLES.map(puzzle => prepareExercise(puzzle));
  return INTERACTIVE_GAMES_MINI_APP_HTML.replaceAll('__OG_TITLE__', title).replaceAll('__OG_DESCRIPTION__', description).replaceAll('__CHESS_TRAINERS_URI__', encodeURIComponent(JSON.stringify(CHESS_TRAINERS))).replaceAll('__CHESS_LESSONS_URI__', encodeURIComponent(JSON.stringify(lessons))).replaceAll('__CHESS_PUZZLES_URI__', encodeURIComponent(JSON.stringify(puzzles)));
}
